use base64::{engine::general_purpose::STANDARD, Engine};
use serde_json::{json, Value};
use sha2::{Digest, Sha256};
use std::{ffi::CString, fs::{self,File},io::{Read,Write},os::unix::{fs::MetadataExt,io::{AsRawFd,FromRawFd}},path::{Component,Path,PathBuf}};
pub const MAX_FILE: usize=8*1024*1024;
pub fn text<'a>(v:&'a Value,key:&str)->Result<&'a str,String>{v.get(key).and_then(Value::as_str).ok_or_else(||format!("{key} must be a string"))}
pub fn args(v:&Value,allowed:&[&str])->Result<(),String>{let o=v.as_object().ok_or("arguments must be an object")?;for k in o.keys(){if !allowed.contains(&k.as_str()){return Err(format!("Unsupported argument: {k}"));}}Ok(())}
pub fn path(s:&str)->Result<PathBuf,String>{let p=if s=="~" {PathBuf::from(std::env::var("HOME").map_err(|e|e.to_string())?)}else if let Some(t)=s.strip_prefix("~/"){PathBuf::from(std::env::var("HOME").map_err(|e|e.to_string())?).join(t)}else{PathBuf::from(s)};if p.is_absolute(){Ok(p)}else{Ok(std::env::current_dir().map_err(|e|e.to_string())?.join(p))}}
fn cstr(s:&std::ffi::OsStr)->Result<CString,String>{use std::os::unix::ffi::OsStrExt;CString::new(s.as_bytes()).map_err(|e|e.to_string())}
fn err()->String{std::io::Error::last_os_error().to_string()}
// Resolve every directory through file descriptors, never following symlinks.
fn parent(p:&Path)->Result<(File,CString),String>{let name=cstr(p.file_name().ok_or("Path must name a file")?)?;let mut dir=File::open("/").map_err(|e|e.to_string())?;for part in p.parent().ok_or("Missing parent")?.components(){match part {Component::RootDir=>{},Component::Normal(s)=>{let c=cstr(s)?;let fd=unsafe{libc::openat(dir.as_raw_fd(),c.as_ptr(),libc::O_RDONLY|libc::O_CLOEXEC|libc::O_DIRECTORY|libc::O_NOFOLLOW)};if fd<0{return Err(err());}dir=unsafe{File::from_raw_fd(fd)};},_=>return Err("Parent traversal is not allowed".into())}}Ok((dir,name))}
fn open_regular(p:&Path)->Result<File,String>{let(d,n)=parent(p)?;let fd=unsafe{libc::openat(d.as_raw_fd(),n.as_ptr(),libc::O_RDONLY|libc::O_CLOEXEC|libc::O_NOFOLLOW|libc::O_NONBLOCK)};if fd<0{return Err(err());}let f=unsafe{File::from_raw_fd(fd)};if !f.metadata().map_err(|e|e.to_string())?.is_file(){return Err("Requires a regular, non-symlink file".into());}Ok(f)}
pub fn bytes(p:&Path)->Result<Vec<u8>,String>{let f=open_regular(p)?;let mut data=Vec::new();f.take((MAX_FILE+1) as u64).read_to_end(&mut data).map_err(|e|e.to_string())?;if data.len()>MAX_FILE{return Err("File exceeds 8 MiB limit; use scp/sftp for larger files".into());}Ok(data)}
pub fn digest(b:&[u8])->String{format!("{:x}",Sha256::digest(b))}
pub fn transfer(method:&str,v:&Value)->Result<Value,String>{let p=path(text(v,"path")?)?;match method{
 "file_get"=>{args(v,&["path"])?;let b=bytes(&p)?;Ok(json!({"data":STANDARD.encode(&b),"sha256":digest(&b),"size":b.len()}))},
 "file_put"=>{args(v,&["path","data","sha256"])?;let encoded=text(v,"data")?;if encoded.len()>MAX_FILE*4/3+8{return Err("File exceeds transfer limit".into());}let b=STANDARD.decode(encoded).map_err(|e|e.to_string())?;let sum=digest(&b);if b.len()>MAX_FILE||sum!=text(v,"sha256")?{return Err("Size or checksum mismatch".into());}let(d,n)=parent(&p)?;let stage=CString::new(format!(".teleoperator-{}-{}",std::process::id(),std::time::SystemTime::now().duration_since(std::time::UNIX_EPOCH).unwrap().as_nanos())).unwrap();let fd=unsafe{libc::openat(d.as_raw_fd(),stage.as_ptr(),libc::O_WRONLY|libc::O_CREAT|libc::O_EXCL|libc::O_CLOEXEC,0o600)};if fd<0{return Err(err());}let mut f=unsafe{File::from_raw_fd(fd)};let res=(||{f.write_all(&b).and_then(|_|f.sync_all()).map_err(|e|e.to_string())?;if unsafe{libc::linkat(d.as_raw_fd(),stage.as_ptr(),d.as_raw_fd(),n.as_ptr(),0)}<0{return Err(err());}Ok(json!({"path":p,"sha256":sum,"size":b.len()}))})();unsafe{libc::unlinkat(d.as_raw_fd(),stage.as_ptr(),0);}res},
 "file_remove"=>{args(v,&["path","sha256"])?;let mut f=open_regular(&p)?;let mut b=Vec::new();Read::by_ref(&mut f).take((MAX_FILE+1) as u64).read_to_end(&mut b).map_err(|e|e.to_string())?;if b.len()>MAX_FILE||digest(&b)!=text(v,"sha256")?{return Err("Source changed; refusing deletion".into());}let(d,n)=parent(&p)?;let meta=f.metadata().map_err(|e|e.to_string())?;let current=open_regular(&p)?.metadata().map_err(|e|e.to_string())?;if meta.ino()!=current.ino()||meta.dev()!=current.dev(){return Err("Source changed; refusing deletion".into());}if unsafe{libc::unlinkat(d.as_raw_fd(),n.as_ptr(),0)}<0{return Err(err());}Ok(json!({"removed":p}))},_=>Err("Unknown transfer method".into())}}
pub fn replace(p:&Path,content:&str)->Result<(),String>{if content.len()>MAX_FILE{return Err("Content exceeds 8 MiB".into());}let(d,n)=parent(p)?;let stage=CString::new(format!(".teleoperator-w-{}-{}",std::process::id(),std::time::SystemTime::now().duration_since(std::time::UNIX_EPOCH).unwrap().as_nanos())).unwrap();let fd=unsafe{libc::openat(d.as_raw_fd(),stage.as_ptr(),libc::O_WRONLY|libc::O_CREAT|libc::O_EXCL|libc::O_CLOEXEC,0o600)};if fd<0{return Err(err());}let mut f=unsafe{File::from_raw_fd(fd)};let res=(||{if let Ok(m)=fs::symlink_metadata(p){if !m.file_type().is_file(){return Err("Requires a regular, non-symlink file".into());}let mode=unsafe{libc::fchmod(f.as_raw_fd(),(m.mode()&0o7777) as libc::mode_t)};if mode<0{return Err(err());}}f.write_all(content.as_bytes()).and_then(|_|f.sync_all()).map_err(|e|e.to_string())?;if unsafe{libc::renameat(d.as_raw_fd(),stage.as_ptr(),d.as_raw_fd(),n.as_ptr())}<0{return Err(err());}Ok(())})();unsafe{libc::unlinkat(d.as_raw_fd(),stage.as_ptr(),0);}res}
pub fn write_text(p:&Path,content:&str)->Result<(),String>{if content.len()>MAX_FILE{return Err("Content exceeds 8 MiB".into());}let(d,n)=parent(p)?;let fd=unsafe{libc::openat(d.as_raw_fd(),n.as_ptr(),libc::O_WRONLY|libc::O_CREAT|libc::O_CLOEXEC|libc::O_NOFOLLOW|libc::O_NONBLOCK,0o600)};if fd<0{return Err(err());}let mut f=unsafe{File::from_raw_fd(fd)};if !f.metadata().map_err(|e|e.to_string())?.is_file(){return Err("Requires a regular file".into());}f.set_len(0).and_then(|_|f.write_all(content.as_bytes())).map_err(|e|e.to_string())}
